<?php require_once __DIR__.'/includes/bootstrap.php';require_role('buyer');if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';if($action==='add'){$id=(int)($_POST['produce_id']??0);$qty=max(1,(int)($_POST['quantity']??1));$st=$pdo->prepare("SELECT id,quantity FROM produce WHERE id=? AND status='approved'");$st->execute([$id]);$p=$st->fetch();if($p&&$qty<=$p['quantity']){$_SESSION['cart'][$id]=min((int)($_SESSION['cart'][$id]??0)+$qty,(int)$p['quantity']);flash('success','Item added to cart.');}else flash('error','Requested quantity is not available.');}elseif($action==='remove'){unset($_SESSION['cart'][(int)($_POST['id']??0)]);}elseif($action==='checkout'){try{$pdo->beginTransaction();$cart=$_SESSION['cart']??[];if(!$cart)throw new Exception('Your cart is empty.');$total=0;$lines=[];foreach($cart as $id=>$qty){$st=$pdo->prepare("SELECT id,name,farmer_id,price,quantity,status FROM produce WHERE id=? FOR UPDATE");$st->execute([(int)$id]);$p=$st->fetch();if(!$p||$p['status']!=='approved'||$qty<1||$qty>$p['quantity'])throw new Exception('An item is no longer available in that quantity. Refresh your cart.');$total+=$p['price']*$qty;$lines[]=[$p,$qty];}$st=$pdo->prepare("INSERT INTO orders(buyer_id,total,status) VALUES(?,?,'pending_approval')");$st->execute([current_user()['id'],$total]);$oid=(int)$pdo->lastInsertId();foreach($lines as [$p,$qty]){$st=$pdo->prepare('INSERT INTO order_items(order_id,produce_id,farmer_id,quantity,unit_price) VALUES(?,?,?,?,?)');$st->execute([$oid,$p['id'],$p['farmer_id'],$qty,$p['price']]);}$pdo->commit();$_SESSION['cart']=[];flash('success','Order submitted for administrator approval. Your order number is #'.$oid.'. Stock will be reserved when the admin approves it.');redirect('orders.php');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('error',$e instanceof PDOException?'Unable to place order. Please try again.':$e->getMessage());}}redirect('cart.php');} $cart=$_SESSION['cart']??[];$rows=[];$total=0;if($cart){$ids=array_keys($cart);$marks=implode(',',array_fill(0,count($ids),'?'));$st=$pdo->prepare("SELECT id,name,price,unit,quantity FROM produce WHERE id IN ($marks)");$st->execute($ids);foreach($st->fetchAll() as $p){$qty=(int)$cart[$p['id']];$sub=$qty*$p['price'];$total+=$sub;$rows[]=[$p,$qty,$sub];}}include __DIR__.'/includes/header.php'; ?>
<section class="page-banner"><span class="eyebrow">YOUR SELECTION</span><h1>Shopping cart</h1></section><section class="section"><?= show_flash() ?><?php if(!$rows): ?><div class="empty">Your cart is empty. <a href="catalogue.php">Browse produce</a>.</div><?php else: ?><div class="panel table-wrap"><table><thead><tr><th>Produce</th><th>Quantity</th><th>Price</th><th>Subtotal</th><th></th></tr></thead><tbody><?php foreach($rows as [$p,$qty,$sub]): ?><tr><td><?= e($p['name']) ?></td><td><?= $qty ?> <?= e($p['unit']) ?></td><td>KSh <?= number_format($p['price'],2) ?></td><td>KSh <?= number_format($sub,2) ?></td><td><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="remove"><input type="hidden" name="id" value="<?= $p['id'] ?>"><button class="link-button">Remove</button></form></td></tr><?php endforeach; ?></tbody></table><div class="cart-total"><h2>Total: KSh <?= number_format($total,2) ?></h2><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="checkout"><button class="btn" type="submit">Place order</button></form></div></div><?php endif; ?></section><?php include __DIR__.'/includes/footer.php'; ?>